        int n = s.length();
        int maxLength = 0;
        int left = 0;
        java.util.HashMap<Character, Integer> lastOccurrence = new java.util.HashMap<>();

        for (int right = 0; right < n; right++) {
            char currentChar = s.charAt(right);

            if (lastOccurrence.containsKey(currentChar) && lastOccurrence.get(currentChar) >= left) {
                left = lastOccurrence.get(currentChar) + 1;
            }

            lastOccurrence.put(currentChar, right);
            maxLength = Math.max(maxLength, right - left + 1);
        }

        return maxLength;
    }
}

