class Solution {
    public int lengthOfLongestSubstring(String s) {
        int n = s.length();
        int maxLength = 0;
        int left = 0;
        java.util.HashMap<Character, Integer> lastOccurrence = new java.util.HashMap<>();

        for (int right = 0; right < n; right++) {
