class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int m = nums1.length;
        int n = nums2.length;
        if (m > n) {
            int[] temp = nums1;
            nums1 = nums2;
            nums2 = temp;
            m = n;
            n = temp.length;
        }
        int low = 0, high = m;
        int median1 = 0, median2 = 0;
        while (low <= high) {
            int mid1 = (low + high) / 2;
            int mid2 = (m + n + 1) / 2 - mid1;
            int max1 = (mid1 == 0) ? Integer.MIN_VALUE : nums1[mid1 - 1];
            int min1 = (mid1 == m) ? Integer.MAX_VALUE : nums1[mid1];
            int max2 = (mid2 == 0) ? Integer.MIN_VALUE : nums2[mid2 - 1];
            int min2 = (mid2 == n) ? Integer.MAX_VALUE : nums2[mid2];
            if (max1 <= min2 && max2 <= min1) {
                median1 = Math.max(max1, max2);
                median2 = Math.min(min1, min2);
                break;
            } else if (max1 > min2) {
                high = mid1 - 1;
            } else {
                low = mid1 + 1;
            }
        }
        return (m + n) % 2 == 0 ? (median1 + median2) / 2.0 : median1;
    }
}

