class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;
        ListNode curr = head;
        int count = 0;

        while (curr != null) {
            count++;
            if (count % k == 0) {
                prev = reverseGroup(prev, curr);
                curr = prev.next;
            } else {
                curr = curr.next;
            }
        }
        return dummy.next;
    }

    private ListNode reverseGroup(ListNode prev, ListNode curr) {
        ListNode last = prev.next;
        ListNode currNext = null;
        ListNode next = null;

        while (curr != null) {
            next = curr.next;
            curr.next = currNext;
            currNext = curr;
            curr = next;
        }

        last.next = currNext;
        prev.next = currNext;
        return last;
    }
}

