import java.util.*;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> result = new ArrayList<>();
        int wordLen = words[0].length();
        int totalLen = words.length * wordLen;
        int sLen = s.length();

        if (sLen < totalLen || words.length == 0) return result;

        Map<String, Integer> wordFreq = new HashMap<>();
        for (String word : words) {
            wordFreq.put(word, wordFreq.getOrDefault(word, 0) + 1);
        }

        for (int i = 0; i < wordLen; i++) {
            Map<String, Integer> windowFreq = new HashMap<>();
            int left = i;
            int right = i;
            int count = 0;

            while (right + wordLen <= sLen) {
                String currentWord = s.substring(right, right + wordLen);
                right += wordLen;

                if (wordFreq.containsKey(currentWord)) {
                    windowFreq.put(currentWord, windowFreq.getOrDefault(currentWord, 0) + 1);
                    if (windowFreq.get(currentWord) == wordFreq.get(currentWord)) {
                        count++;
                    }
                }

                while (right - left > totalLen) {
                    String leftWord = s.substring(left, left + wordLen);
                    if (wordFreq.containsKey(leftWord)) {
                        if (windowFreq.get(leftWord) == wordFreq.get(leftWord)) {
                            count--;
                        }
                        windowFreq.put(leftWord, windowFreq.get(leftWord) - 1);
                    }
                    left += wordLen;
                }

                if (count == wordFreq.size()) {
                    result.add(left);
                }
            }
        }
        return result;
    }
}

