import java.util.*;

class Solution {
    public List<List<String>> groupAnagrams(String[] strs) {
        Map<Long, List<String>> map = new HashMap<>();

        for (String s : strs) {
            long key = getPrimeProduct(s);
            map.putIfAbsent(key, new ArrayList<>());
            map.get(key).add(s);
        }

