class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        List<String> result = new ArrayList<>();
        int n = words.length;
        int index = 0;

        while (index < n) {
            int lineLength = 0;
            int wordCount = 0;
            List<String> lineWords = new ArrayList<>();

            // Pack words into the current line
            while (index < n && lineLength + words[index].length() <= maxWidth) {
                lineLength += words[index].length();
                wordCount++;
                lineWords.add(words[index++]);
            }

            // Handle the current line
            if (lineWords.isEmpty()) {
                continue;
            }

            if (index == n || wordCount == 1) {
                // Last line or single word line: left-justify
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < wordCount - 1; i++) {
                    sb.append(lineWords.get(i)).append(' ');
                }
                sb.append(lineWords.get(wordCount - 1));

                // Add padding spaces to reach maxWidth
                int padding = maxWidth - sb.length();
                sb.append(' '.repeat(padding));
                result.add(sb.toString());
            } else {
                // Fully justify the line
                int totalSpaces = maxWidth - lineLength;
                int spacesPerSlot = totalSpaces / (wordCount - 1);
                int extraSpaces = totalSpaces % (wordCount - 1);

                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < wordCount; i++) {
                    sb.append(lineWords.get(i));
                    if (i < wordCount - 1) {
                        int spaces = spacesPerSlot + (extraSpaces-- > 0 ? 1 : 0);
                        sb.append(' '.repeat(spaces));
                    }
                }
                result.add(sb.toString());
            }
        }
        return result;
    }
}

